CREATE TABLE IF NOT EXISTS reference_imports (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('historical_tables','census_provinces')), version TEXT NOT NULL, source_name TEXT NOT NULL, source_sha256 TEXT NOT NULL, source_year INTEGER NOT NULL, source_label TEXT NOT NULL, row_count INTEGER NOT NULL CHECK(row_count > 0), imported_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(kind,version), UNIQUE(kind,source_sha256));
CREATE TABLE IF NOT EXISTS historical_table_references (import_id TEXT NOT NULL REFERENCES reference_imports(id), raw_code TEXT NOT NULL, community_code TEXT NOT NULL, community_name TEXT NOT NULL, province_code TEXT NOT NULL, province_name TEXT NOT NULL, municipality_code TEXT NOT NULL, municipality_name TEXT NOT NULL, district TEXT NOT NULL, section TEXT NOT NULL, table_label TEXT NOT NULL, is_exterior BOOLEAN NOT NULL, historical_census INTEGER NOT NULL CHECK(historical_census >= 0), PRIMARY KEY(import_id,raw_code), UNIQUE(import_id,province_code,municipality_code,district,section,table_label));
CREATE INDEX IF NOT EXISTS historical_table_ref_location ON historical_table_references(import_id,province_code,municipality_code);
CREATE TABLE IF NOT EXISTS census_province_references (import_id TEXT NOT NULL REFERENCES reference_imports(id), province_code TEXT NOT NULL, province_name TEXT NOT NULL, residents_spain INTEGER NOT NULL CHECK(residents_spain >= 0), residents_abroad INTEGER NOT NULL CHECK(residents_abroad >= 0), total INTEGER NOT NULL CHECK(total = residents_spain + residents_abroad), PRIMARY KEY(import_id,province_code));
